DROP POLICY IF EXISTS message_reactions_insert_policy ON public.message_reactions

CREATE POLICY message_reactions_insert_policy ON public.message_reactions FOR INSERT TO authenticated WITH CHECK (user_id = public.get_profile_id_for_user(auth.uid()) AND EXISTS (SELECT 1 FROM public.messages m JOIN public.contacts c ON c.id = m.contact_id WHERE m.id = message_id AND (public.is_admin_or_supervisor(auth.uid()) OR m.contact_id IN (SELECT c2.id FROM public.contacts c2 WHERE c2.assigned_to IN (SELECT public.get_visible_agent_ids(auth.uid()))) OR EXISTS (SELECT 1 FROM public.contacts c3 JOIN public.queue_members qm ON qm.queue_id = c3.queue_id WHERE c3.id = m.contact_id AND qm.profile_id = public.get_profile_id_for_user(auth.uid()) AND qm.is_active = true))))

DROP POLICY IF EXISTS message_reactions_update_policy ON public.message_reactions

CREATE POLICY message_reactions_update_policy ON public.message_reactions FOR UPDATE TO authenticated USING (user_id = public.get_profile_id_for_user(auth.uid()) AND EXISTS (SELECT 1 FROM public.messages m JOIN public.contacts c ON c.id = m.contact_id WHERE m.id = message_id AND (public.is_admin_or_supervisor(auth.uid()) OR m.contact_id IN (SELECT c2.id FROM public.contacts c2 WHERE c2.assigned_to IN (SELECT public.get_visible_agent_ids(auth.uid()))) OR EXISTS (SELECT 1 FROM public.contacts c3 JOIN public.queue_members qm ON qm.queue_id = c3.queue_id WHERE c3.id = m.contact_id AND qm.profile_id = public.get_profile_id_for_user(auth.uid()) AND qm.is_active = true)))) WITH CHECK (user_id = public.get_profile_id_for_user(auth.uid()) AND EXISTS (SELECT 1 FROM public.messages m JOIN public.contacts c ON c.id = m.contact_id WHERE m.id = message_id AND (public.is_admin_or_supervisor(auth.uid()) OR m.contact_id IN (SELECT c2.id FROM public.contacts c2 WHERE c2.assigned_to IN (SELECT public.get_visible_agent_ids(auth.uid()))) OR EXISTS (SELECT 1 FROM public.contacts c3 JOIN public.queue_members qm ON qm.queue_id = c3.queue_id WHERE c3.id = m.contact_id AND qm.profile_id = public.get_profile_id_for_user(auth.uid()) AND qm.is_active = true))))

DROP POLICY IF EXISTS message_reactions_delete_policy ON public.message_reactions

CREATE POLICY message_reactions_delete_policy ON public.message_reactions FOR DELETE TO authenticated USING (user_id = public.get_profile_id_for_user(auth.uid()) AND EXISTS (SELECT 1 FROM public.messages m JOIN public.contacts c ON c.id = m.contact_id WHERE m.id = message_id AND (public.is_admin_or_supervisor(auth.uid()) OR m.contact_id IN (SELECT c2.id FROM public.contacts c2 WHERE c2.assigned_to IN (SELECT public.get_visible_agent_ids(auth.uid()))) OR EXISTS (SELECT 1 FROM public.contacts c3 JOIN public.queue_members qm ON qm.queue_id = c3.queue_id WHERE c3.id = m.contact_id AND qm.profile_id = public.get_profile_id_for_user(auth.uid()) AND qm.is_active = true))))
